/* ===== LearnForge — Design System ===== */
:root {
  --color-black: #000000;
  --color-lime: #E6FF32;
  --color-burgundy: #7F2A23;
  --color-white: #FFFFFF;
  --color-off-white: #F8F9FA;
  --color-gray-50: #F9FAFB;
  --color-gray-100: #F3F4F6;
  --color-gray-200: #E5E7EB;
  --color-gray-300: #D1D5DB;
  --color-gray-400: #9CA3AF;
  --color-gray-500: #6B7280;
  --color-gray-600: #4B5563;
  --color-gray-700: #374151;
  --color-gray-800: #1F2937;
  --color-gray-900: #111827;

  --font-heading: 'Inter', 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.04);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;

  --max-width: 1200px;
  --nav-height: 72px;
}

/* ===== Reset ===== */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-800);
  background: var(--color-white);
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  color: var(--color-black);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(2rem, 4vw, 3rem); letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.75rem); }
h4 { font-size: 1.25rem; }

.section-label {
  display: inline-block;
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-burgundy);
  margin-bottom: 0.75rem;
}

.section-title {
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--color-gray-500);
  max-width: 600px;
  line-height: 1.7;
}

/* ===== Layout ===== */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

.section {
  padding: 6rem 0;
}

.section-header {
  text-align: center;
  margin-bottom: 4rem;
}

.section-header .section-subtitle {
  margin: 0 auto;
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all 0.2s ease;
  white-space: nowrap;
  font-family: var(--font-body);
}

.btn-primary {
  background: var(--color-lime);
  color: var(--color-black);
}

.btn-primary:hover {
  background: #d4ed2a;
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: var(--color-black);
  color: var(--color-white);
}

.btn-secondary:hover {
  background: var(--color-gray-800);
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-outline {
  border: 2px solid var(--color-gray-200);
  color: var(--color-black);
}

.btn-outline:hover {
  border-color: var(--color-lime);
  background: var(--color-gray-50);
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1.1rem;
  border-radius: var(--radius-lg);
}

/* ===== Navigation ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-gray-100);
  z-index: 1000;
  display: flex;
  align-items: center;
}

.nav .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-black);
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-600);
  transition: color 0.2s;
}

.nav-links a:hover { color: var(--color-black); }

.nav-cta {
  background: var(--color-lime) !important;
  color: var(--color-black) !important;
  padding: 0.625rem 1.25rem !important;
  border-radius: var(--radius-sm) !important;
  font-weight: 600 !important;
}

.nav-cta:hover {
  background: #d4ed2a !important;
  color: var(--color-black) !important;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-black);
  transition: all 0.3s;
}

.nav-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav-toggle.active span:nth-child(2) { opacity: 0; }
.nav-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ===== Hero ===== */
.hero {
  padding: calc(var(--nav-height) + 4rem) 0 4rem;
  background: var(--color-black);
  color: var(--color-white);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(230,255,50,0.06) 0%, transparent 70%);
  border-radius: 50%;
}

.hero .container {
  position: relative;
  z-index: 1;
}

.hero-content {
  text-align: center;
  max-width: 800px;
  margin: 0 auto 3rem;
}

.hero h1 {
  color: var(--color-white);
  margin-bottom: 1.25rem;
}

.hero-subtitle {
  font-size: 1.2rem;
  color: var(--color-gray-400);
  line-height: 1.7;
  margin-bottom: 2rem;
}

.hero-buttons {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-preview {
  background: var(--color-gray-900);
  border: 1px solid var(--color-gray-800);
  border-radius: var(--radius-xl);
  overflow: hidden;
  max-width: 900px;
  margin: 0 auto;
  box-shadow: var(--shadow-xl);
}

.hero-preview-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  background: var(--color-gray-800);
}

.hero-preview-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-gray-600);
}

.hero-preview-dot:nth-child(1) { background: #FF5F56; }
.hero-preview-dot:nth-child(2) { background: #FFBD2E; }
.hero-preview-dot:nth-child(3) { background: #27C93F; }

/* Hero Tabs */
.hero-tabs {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-bottom: 2rem;
}

.hero-tab {
  padding: 0.625rem 1.5rem;
  border-radius: 100px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-400);
  background: rgba(255,255,255,0.05);
  transition: all 0.3s;
  border: 1px solid transparent;
}

.hero-tab.active {
  background: rgba(230,255,50,0.1);
  color: var(--color-lime);
  border-color: var(--color-lime);
}

.hero-tab:hover:not(.active) {
  color: var(--color-white);
  background: rgba(255,255,255,0.08);
}

.hero-tab-panel {
  display: none;
  padding: 2rem;
  text-align: center;
  min-height: 300px;
  align-items: center;
  justify-content: center;
}

.hero-tab-panel.active {
  display: flex;
  flex-direction: column;
}

.hero-tab-panel .preview-label {
  font-size: 0.875rem;
  color: var(--color-gray-500);
  margin-bottom: 1rem;
}

.hero-tab-panel .preview-content {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  width: 100%;
}

.preview-card {
  background: var(--color-gray-800);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  text-align: left;
}

.preview-card-icon {
  width: 36px;
  height: 36px;
  background: rgba(230,255,50,0.15);
  border-radius: var(--radius-sm);
  margin-bottom: 0.75rem;
}

.preview-card-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-white);
  margin-bottom: 0.25rem;
}

.preview-card-sub {
  font-size: 0.75rem;
  color: var(--color-gray-400);
}

/* ===== Stats Bar ===== */
.stats-bar {
  background: var(--color-black);
  border-top: 1px solid var(--color-gray-800);
  border-bottom: 1px solid var(--color-gray-800);
}

.stats-bar .container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

.stat-item {
  text-align: center;
  padding: 2.5rem 1.5rem;
  position: relative;
}

.stat-item:not(:last-child)::after {
  content: '';
  position: absolute;
  right: 0;
  top: 25%;
  height: 50%;
  width: 1px;
  background: var(--color-gray-800);
}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 3vw, 2.75rem);
  font-weight: 800;
  color: var(--color-lime);
  line-height: 1;
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.9375rem;
  color: var(--color-gray-400);
  font-weight: 500;
}

/* ===== Products Grid ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}

.product-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s;
  cursor: pointer;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
  border-color: var(--color-lime);
}

.product-card-icon {
  width: 48px;
  height: 48px;
  background: var(--color-gray-50);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1.25rem;
}

.product-card h3 {
  margin-bottom: 0.5rem;
}

.product-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ===== Why Choose Us Tabs ===== */
.why-tabs-nav {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-bottom: 3rem;
  flex-wrap: wrap;
}

.why-tab-btn {
  padding: 0.75rem 1.5rem;
  border-radius: 100px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-500);
  background: var(--color-gray-50);
  transition: all 0.3s;
  border: 2px solid transparent;
}

.why-tab-btn.active {
  background: var(--color-black);
  color: var(--color-lime);
  border-color: var(--color-lime);
}

.why-tab-btn:hover:not(.active) {
  background: var(--color-gray-100);
  color: var(--color-gray-700);
}

.why-tab-panel {
  display: none;
}

.why-tab-panel.active {
  display: block;
}

.why-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.why-feature-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 1rem;
  background: var(--color-gray-50);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  color: var(--color-gray-700);
}

.why-feature-check {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  background: var(--color-lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-black);
}

/* ===== Feature Cards ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.feature-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s;
}

.feature-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.feature-card-icon {
  width: 48px;
  height: 48px;
  background: rgba(127,42,35,0.08);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1.25rem;
}

.feature-card h3 {
  margin-bottom: 0.5rem;
}

.feature-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ===== Global Scale ===== */
.global-scale {
  background: var(--color-gray-50);
  text-align: center;
}

.global-map {
  max-width: 700px;
  margin: 3rem auto 0;
}

.global-map-placeholder {
  background: var(--color-gray-200);
  border-radius: var(--radius-xl);
  padding: 4rem 2rem;
  font-size: 1.25rem;
  color: var(--color-gray-500);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

.global-map-icon {
  font-size: 4rem;
}

/* ===== AI Section ===== */
.ai-section {
  background: var(--color-black);
  color: var(--color-white);
}

.ai-section .section-label {
  color: var(--color-lime);
}

.ai-section h2, .ai-section h3 {
  color: var(--color-white);
}

.ai-section .section-subtitle {
  color: var(--color-gray-400);
}

.ai-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.ai-card {
  background: var(--color-gray-900);
  border: 1px solid var(--color-gray-800);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s;
}

.ai-card:hover {
  border-color: var(--color-lime);
  transform: translateY(-2px);
}

.ai-card-icon {
  width: 44px;
  height: 44px;
  background: rgba(230,255,50,0.12);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.35rem;
  margin-bottom: 1.25rem;
}

.ai-card h3 {
  margin-bottom: 0.5rem;
}

.ai-card p {
  color: var(--color-gray-400);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ===== Testimonials ===== */
.testimonials { background: var(--color-off-white); }

.testimonials-carousel {
  position: relative;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 0 1rem;
}

.testimonial-card-inner {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 3rem;
  box-shadow: var(--shadow-md);
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.25rem;
  line-height: 1.7;
  color: var(--color-gray-700);
  font-style: italic;
  margin-bottom: 1.5rem;
}

.testimonial-author {
  font-weight: 700;
  color: var(--color-black);
  margin-bottom: 0.25rem;
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

.testimonial-badge {
  display: inline-block;
  background: var(--color-lime);
  color: var(--color-black);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.75rem;
  border-radius: 100px;
  margin-bottom: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  border: 2px solid var(--color-gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--color-black);
  transition: all 0.2s;
}

.carousel-btn:hover {
  background: var(--color-lime);
  border-color: var(--color-lime);
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-gray-300);
  border: none;
  cursor: pointer;
  transition: all 0.3s;
}

.carousel-dot.active {
  background: var(--color-lime);
  width: 28px;
  border-radius: 100px;
}

/* ===== Pricing ===== */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
  align-items: start;
}

.pricing-card {
  background: var(--color-white);
  border: 2px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  padding: 2rem;
  text-align: center;
  transition: all 0.3s;
}

.pricing-card.featured {
  border-color: var(--color-lime);
  box-shadow: var(--shadow-xl);
  transform: scale(1.03);
}

.pricing-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.pricing-card.featured:hover {
  transform: scale(1.03) translateY(-4px);
}

.pricing-name {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-black);
  margin-bottom: 0.25rem;
}

.pricing-period {
  font-size: 0.875rem;
  color: var(--color-gray-500);
  margin-bottom: 1.5rem;
}

.pricing-features {
  text-align: left;
  margin-bottom: 1.5rem;
}

.pricing-features li {
  padding: 0.5rem 0;
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  border-bottom: 1px solid var(--color-gray-100);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.pricing-features li::before {
  content: '✓';
  color: var(--color-lime);
  font-weight: 700;
  font-size: 0.875rem;
}

.pricing-card .btn {
  width: 100%;
}

.pricing-note {
  text-align: center;
  margin-top: 1.5rem;
  font-size: 0.9375rem;
  color: var(--color-gray-500);
}

.pricing-note a {
  color: var(--color-black);
  font-weight: 600;
  text-decoration: underline;
}

/* Enterprise */
.enterprise-card {
  background: var(--color-black);
  color: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 3rem;
  margin-top: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.enterprise-card h3 {
  color: var(--color-white);
  margin-bottom: 0.5rem;
}

.enterprise-card p {
  color: var(--color-gray-400);
  font-size: 0.9375rem;
}

.enterprise-features {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 1rem;
}

.enterprise-feature-tag {
  background: rgba(230,255,50,0.1);
  color: var(--color-lime);
  font-size: 0.8125rem;
  font-weight: 500;
  padding: 0.375rem 0.75rem;
  border-radius: 100px;
}

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1rem;
}

.integration-item {
  aspect-ratio: 3/2;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-gray-600);
  transition: all 0.3s;
  cursor: default;
}

.integration-item:hover {
  border-color: var(--color-lime);
  box-shadow: var(--shadow-md);
