  display: none;
  padding: 2rem;
  text-align: center;
  min-height: 300px;
  align-items: center;
  justify-content: center;
}

.hero-tab-panel.active {
  display: flex;
  flex-direction: column;
}

.hero-tab-panel .preview-label {
  font-size: 0.875rem;
  color: var(--color-gray-500);
  margin-bottom: 1rem;
}

.hero-tab-panel .preview-content {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  width: 100%;
}

.preview-card {
  background: var(--color-gray-800);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  text-align: left;
}

.preview-card-icon {
  width: 36px;
  height: 36px;
  background: rgba(230,255,50,0.15);
  border-radius: var(--radius-sm);
  margin-bottom: 0.75rem;
}

.preview-card-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-white);
  margin-bottom: 0.25rem;
}

.preview-card-sub {
  font-size: 0.75rem;
  color: var(--color-gray-400);
}

/* ===== Stats Bar ===== */
.stats-bar {
  background: var(--color-black);
  border-top: 1px solid var(--color-gray-800);
  border-bottom: 1px solid var(--color-gray-800);
}

.stats-bar .container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

.stat-item {
  text-align: center;
  padding: 2.5rem 1.5rem;
  position: relative;
}

.stat-item:not(:last-child)::after {
  content: '';
  position: absolute;
  right: 0;
  top: 25%;
  height: 50%;
  width: 1px;
  background: var(--color-gray-800);
}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 3vw, 2.75rem);
  font-weight: 800;
  color: var(--color-lime);
  line-height: 1;
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.9375rem;
  color: var(--color-gray-400);
  font-weight: 500;
}

/* ===== Products Grid ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}

.product-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s;
  cursor: pointer;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
  border-color: var(--color-lime);
}

.product-card-icon {
  width: 48px;
  height: 48px;
  background: var(--color-gray-50);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1.25rem;
}

.product-card h3 {
  margin-bottom: 0.5rem;
}

.product-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ===== Why Choose Us Tabs ===== */
.why-tabs-nav {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-bottom: 3rem;
  flex-wrap: wrap;
}

.why-tab-btn {
  padding: 0.75rem 1.5rem;
  border-radius: 100px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-500);
  background: var(--color-gray-50);
  transition: all 0.3s;
  border: 2px solid transparent;
}

.why-tab-btn.active {
  background: var(--color-black);
  color: var(--color-lime);
  border-color: var(--color-lime);
}

.why-tab-btn:hover:not(.active) {
  background: var(--color-gray-100);
  color: var(--color-gray-700);
}

.why-tab-panel {
  display: none;
}

.why-tab-panel.active {
  display: block;
}

.why-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.why-feature-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 1rem;
  background: var(--color-gray-50);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  color: var(--color-gray-700);
}

.why-feature-check {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  background: var(--color-lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-black);
}

/* ===== Feature Cards ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.feature-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s;
}

.feature-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.feature-card-icon {
  width: 48px;
  height: 48px;
  background: rgba(127,42,35,0.08);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1.25rem;
}

.feature-card h3 {
  margin-bottom: 0.5rem;
}

.feature-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ===== Global Scale ===== */
.global-scale {
  background: var(--color-gray-50);
  text-align: center;
}

.global-map {
  max-width: 700px;
  margin: 3rem auto 0;
}

.global-map-placeholder {
  background: var(--color-gray-200);
  border-radius: var(--radius-xl);
  padding: 4rem 2rem;
  font-size: 1.25rem;
  color: var(--color-gray-500);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

.global-map-icon {
  font-size: 4rem;
}

/* ===== AI Section ===== */
.ai-section {
  background: var(--color-black);
  color: var(--color-white);
}

.ai-section .section-label {
  color: var(--color-lime);
}

.ai-section h2, .ai-section h3 {
  color: var(--color-white);
}

.ai-section .section-subtitle {
  color: var(--color-gray-400);
}

.ai-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.ai-card {
  background: var(--color-gray-900);
  border: 1px solid var(--color-gray-800);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s;
}

.ai-card:hover {
  border-color: var(--color-lime);
  transform: translateY(-2px);
}

.ai-card-icon {
  width: 44px;
  height: 44px;
  background: rgba(230,255,50,0.12);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.35rem;
  margin-bottom: 1.25rem;
}

.ai-card h3 {
  margin-bottom: 0.5rem;
}

.ai-card p {
  color: var(--color-gray-400);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ===== Testimonials ===== */
.testimonials { background: var(--color-off-white); }

.testimonials-carousel {
  position: relative;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 0 1rem;
}

.testimonial-card-inner {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 3rem;
  box-shadow: var(--shadow-md);
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.25rem;
  line-height: 1.7;
  color: var(--color-gray-700);
  font-style: italic;
  margin-bottom: 1.5rem;
}

.testimonial-author {
  font-weight: 700;
  color: var(--color-black);
  margin-bottom: 0.25rem;
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

.testimonial-badge {
  display: inline-block;
  background: var(--color-lime);
  color: var(--color-black);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.75rem;
  border-radius: 100px;
  margin-bottom: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  border: 2px solid var(--color-gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--color-black);
  transition: all 0.2s;
}

.carousel-btn:hover {
  background: var(--color-lime);
  border-color: var(--color-lime);
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-gray-300);
  border: none;
  cursor: pointer;
  transition: all 0.3s;
}

.carousel-dot.active {
  background: var(--color-lime);
  width: 28px;
  border-radius: 100px;
}

/* ===== Pricing ===== */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
  align-items: start;
}

.pricing-card {
  background: var(--color-white);
  border: 2px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  padding: 2rem;
  text-align: center;
  transition: all 0.3s;
}

.pricing-card.featured {
  border-color: var(--color-lime);
  box-shadow: var(--shadow-xl);
  transform: scale(1.03);
}

.pricing-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.pricing-card.featured:hover {
  transform: scale(1.03) translateY(-4px);
}

.pricing-name {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-black);
  margin-bottom: 0.25rem;
}

.pricing-period {
  font-size: 0.875rem;
  color: var(--color-gray-500);
  margin-bottom: 1.5rem;
}

.pricing-features {
  text-align: left;
  margin-bottom: 1.5rem;
}

.pricing-features li {
  padding: 0.5rem 0;
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  border-bottom: 1px solid var(--color-gray-100);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.pricing-features li::before {
  content: '✓';
  color: var(--color-lime);
  font-weight: 700;
  font-size: 0.875rem;
}

.pricing-card .btn {
  width: 100%;
}

.pricing-note {
  text-align: center;
  margin-top: 1.5rem;
  font-size: 0.9375rem;
  color: var(--color-gray-500);
}

.pricing-note a {
  color: var(--color-black);
  font-weight: 600;
  text-decoration: underline;
}

/* Enterprise */
.enterprise-card {
  background: var(--color-black);
  color: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 3rem;
  margin-top: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.enterprise-card h3 {
  color: var(--color-white);
  margin-bottom: 0.5rem;
}

.enterprise-card p {
  color: var(--color-gray-400);
  font-size: 0.9375rem;
}

.enterprise-features {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 1rem;
}

.enterprise-feature-tag {
  background: rgba(230,255,50,0.1);
  color: var(--color-lime);
  font-size: 0.8125rem;
  font-weight: 500;
  padding: 0.375rem 0.75rem;
  border-radius: 100px;
}

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1rem;
}

.integration-item {
  aspect-ratio: 3/2;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-gray-600);
  transition: all 0.3s;
  cursor: default;
}

.integration-item:hover {
  border-color: var(--color-lime);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
  color: var(--color-black);
}

/* ===== FAQ ===== */
.faq { background: var(--color-off-white); }

.faq-list {
  max-width: 700px;
  margin: 0 auto;
}

.faq-item {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  margin-bottom: 0.75rem;
  overflow: hidden;
  transition: all 0.3s;
}

.faq-item.active {
  border-color: var(--color-lime);
  box-shadow: var(--shadow-md);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-black);
  text-align: left;
  gap: 1rem;
}

.faq-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--color-gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  transition: all 0.3s;
  color: var(--color-gray-600);
}

.faq-item.active .faq-icon {
  background: var(--color-lime);
  color: var(--color-black);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

.faq-answer-content {
  padding: 0 1.25rem 1.25rem;
  color: var(--color-gray-600);
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* ===== CTA Banner ===== */
.cta-banner {
  background: var(--color-black);
  text-align: center;
  padding: 5rem 0;
}

.cta-banner h2 {
  color: var(--color-white);
  margin-bottom: 1rem;
}

.cta-banner p {
  color: var(--color-gray-400);
  font-size: 1.125rem;
  margin-bottom: 2rem;
}

.cta-banner .btn-primary {
  font-size: 1.1rem;
  padding: 1rem 2.5rem;
}

/* ===== Social Proof ===== */
.social-proof {
  text-align: center;
}

.social-proof-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3rem;
  flex-wrap: wrap;
  margin-top: 2rem;
}

.social-proof-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-gray-400);
  letter-spacing: -0.01em;
  transition: color 0.3s;
}

.social-proof-logo:hover { color: var(--color-gray-600); }

/* ===== Footer ===== */
.footer {
  background: var(--color-black);
  color: var(--color-gray-400);
  padding: 5rem 0 3rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

.footer-brand h3 {
  color: var(--color-white);
  margin-bottom: 0.75rem;
}

.footer-brand p {
  font-size: 0.9375rem;
  line-height: 1.7;
}

.footer-col h4 {
  color: var(--color-white);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1rem;
}

.footer-col ul li { margin-bottom: 0.5rem; }

.footer-col ul li a {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  transition: color 0.2s;
}

.footer-col ul li a:hover { color: var(--color-lime); }

.footer-bottom {
  border-top: 1px solid var(--color-gray-800);
  padding-top: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.875rem;
}

/* ===== Page Hero Variants ===== */
.page-hero {
  padding: calc(var(--nav-height) + 4rem) 0 4rem;
  background: var(--color-black);
  color: var(--color-white);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.05) 0%, transparent 70%);
  border-radius: 50%;
}

.page-hero .container {
  position: relative;
  z-index: 1;
}

.page-hero h1 {
  color: var(--color-white);
  margin-bottom: 1rem;
}

.page-hero .hero-subtitle {
  max-width: 650px;
  margin: 0 auto 2rem;
}

/* ===== Steps ===== */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.step-card {
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  background: var(--color-lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-black);
  margin: 0 auto 1.25rem;
}

.step-card h3 { margin-bottom: 0.5rem; }

.step-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ===== Resources ===== */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.resource-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s;
  cursor: pointer;
}

.resource-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
  border-color: var(--color-lime);
}

.resource-card-type {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-burgundy);
  margin-bottom: 0.5rem;
}

.resource-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
}

.resource-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ===== Tools Grid ===== */
.tools-grid-section {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 0.75rem;
}

.tool-tag {
  background: var(--color-gray-50);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-sm);
  padding: 0.75rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-gray-700);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.2s;
}

.tool-tag:hover {
  border-color: var(--color-lime);
  background: var(--color-white);
}

.tool-tag-icon {
  width: 8px;
  height: 8px;
  background: var(--color-lime);
  border-radius: 50%;
  flex-shrink: 0;
}

/* ===== Coaching Spotlight ===== */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.spotlight-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all 0.3s;
}

.spotlight-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.spotlight-name {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.spotlight-desc {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ===== File Types Grid ===== */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.file-type-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  transition: all 0.3s;
}

.file-type-card:hover {
  border-color: var(--color-lime);
  transform: translateY(-1px);
}

.file-type-icon {
  width: 44px;
  height: 44px;
  background: var(--color-gray-50);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.file-type-name {
  font-weight: 600;
  color: var(--color-black);
}

/* ===== Product Demo ===== */
.product-demo-accordion {
  max-width: 900px;
  margin: 0 auto;
}

.product-demo-toggle {
  width: 100%;
  background: var(--color-gray-50);
  border: 2px dashed var(--color-gray-300);
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-gray-600);
  transition: all 0.3s;
  cursor: pointer;
}

.product-demo-toggle:hover {
  border-color: var(--color-lime);
  background: var(--color-white);
}

.product-demo-toggle.active {
  border-style: solid;
  border-color: var(--color-lime);
  background: var(--color-white);
}

.product-demo-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.5s ease;
}

.product-demo-content.open {
  max-height: 500px;
}

.product-demo-inner {
  background: var(--color-gray-900);
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
  padding: 2rem;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.demo-screenshot {
  background: var(--color-gray-800);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  text-align: center;
  color: var(--color-gray-500);
}

.demo-screenshot-icon {
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

/* ===== Animation ===== */
.fade-in {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.fade-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(4, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-brand { grid-column: 1 / -1; }
  .tools-grid-section { grid-template-columns: repeat(3, 1fr); }
  .ai-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links {
    position: fixed;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--color-white);
    flex-direction: column;
    padding: 1.5rem 2rem;
    gap: 1rem;
    border-bottom: 1px solid var(--color-gray-100);
    transform: translateY(-100%);
    opacity: 0;
    pointer-events: none;
    transition: all 0.3s;
  }

  .nav-links.open {
    transform: translateY(0);
    opacity: 1;
    pointer-events: all;
  }

  .nav-toggle { display: flex; }

  .hero-preview-header { display: none; }
  .hero-tab-panel .preview-content { grid-template-columns: 1fr; }

  .products-grid { grid-template-columns: 1fr 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .why-features-grid { grid-template-columns: 1fr; }
  .pricing-grid { grid-template-columns: 1fr; }
  .pricing-card.featured { transform: scale(1); }
  .pricing-card.featured:hover { transform: translateY(-4px); }
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
  .stats-bar .container { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .enterprise-card { flex-direction: column; text-align: center; }
  .tools-grid-section { grid-template-columns: repeat(2, 1fr); }
  .steps-grid { grid-template-columns: 1fr; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .file-types-grid { grid-template-columns: repeat(2, 1fr); }
  .ai-grid { grid-template-columns: 1fr; }

  .stat-item { padding: 1.5rem 1rem; }
  .stat-value { font-size: 1.5rem; }
}

@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .section { padding: 4rem 0; }
  .products-grid { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-bar .container { grid-template-columns: 1fr; }
  .stat-item:not(:last-child)::after { display: none; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 1rem; text-align: center; }
  .hero-buttons { flex-direction: column; align-items: center; }
  .hero-tabs { flex-direction: column; align-items: center; }
}
